import { ref } from "vue"
import { systemLanguage } from "../../../shared/locale"

/**
 * Translations.
 *
 * Simplified Chinese is the default and the reference: it is the language the
 * app is designed against, so it is the complete table. Lookups fall back to
 * English and then to the key itself, which means a missing string shows up as
 * a visible key rather than an empty label.
 */
export const LANGUAGES = [
  { id: "zh-CN", label: "简体中文" },
  { id: "zh-TW", label: "繁體中文" },
  { id: "en", label: "English" },
  { id: "ar", label: "العربية" },
  { id: "bs", label: "Bosanski" },
  { id: "da", label: "Dansk" },
  { id: "de", label: "Deutsch" },
  { id: "es", label: "Español" },
  { id: "fr", label: "Français" },
  { id: "ja", label: "日本語" },
  { id: "ko", label: "한국어" },
  { id: "nb", label: "Norsk" },
  { id: "pl", label: "Polski" },
  { id: "pt-BR", label: "Português (Brasil)" },
  { id: "ru", label: "Русский" },
  { id: "th", label: "ไทย" },
  { id: "tr", label: "Türkçe" },
  { id: "uk", label: "Українська" },
] as const

export type Language = (typeof LANGUAGES)[number]["id"]

/**
 * The language to start in when nobody has chosen one: the machine's locale
 * mapped onto the tables by the rule the backend uses for the reply language
 * (`systemLanguage`), so zh-HK reads Traditional and nn reads Norwegian on
 * both sides.
 */
export function detectLanguage(tag = machineLocale()): Language {
  return systemLanguage(tag)
}

/*
 * The locale the main process reads with `app.getLocale()` and hands the
 * backend too, so the interface and the reply language come from one source
 * (MiMo's). The page's own navigator answer is only for a page without the
 * bridge.
 */
function machineLocale(): string {
  try {
    const tag = typeof window === "object" ? window.mcode?.systemLocale?.() : undefined
    if (tag) return tag
  } catch {
    // No main process to ask.
  }
  return typeof navigator === "object" ? navigator.language : ""
}

/**
 * Languages written right to left.
 *
 * Setting `dir` on the document is what makes the whole interface mirror -
 * every rule that uses a logical property (padding-inline, margin-inline-start)
 * follows it, which is why those were used in the first place.
 */
export const RTL_LANGUAGES: readonly string[] = ["ar"]

export const language = ref<Language>("zh-CN")

