// --- end generated language tables ---

/*
 * Every table, by language. In a build, `languageChunks` in
 * electron.vite.config.ts moves each one but zh-CN (the default) and en (the
 * fallback) into a chunk of its own - sixteen tables were 1.9MB of a 5.9MB
 * entry chunk, parsed before the window could draw - and fills LOADERS with
 * how to fetch it, so `loadLanguage` has to have run before `language` is set
 * to one of them. MiMo loads its language tables the same way. Unbuilt - the
 * checks import this file under node - every table is here from the start.
 */
const TABLES: Partial<Record<Language, Table>> = {
  "zh-CN": zhCN,
  "zh-TW": zhTW,
  en,
  "ar": ar,
  "bs": bs,
  "da": da,
  "de": de,
  "es": es,
  "fr": fr,
  "ja": ja,
  "ko": ko,
  "nb": nb,
  "pl": pl,
  "pt-BR": ptBR,
  "ru": ru,
  "th": th,
  "tr": tr,
  "uk": uk,
}
const LOADERS: Partial<Record<Language, () => Promise<Table>>> = {}

/** Whether a language's table is in hand, so switching to it draws its words at once. */
export function languageReady(id: Language): boolean {
  return Boolean(TABLES[id])
}

/** Fetches a language's table if the build left it out of the entry; a failed fetch leaves English showing through. */
export async function loadLanguage(id: Language): Promise<void> {
  if (TABLES[id]) return
  const load = LOADERS[id]
  if (!load) return
  try {
    TABLES[id] = await load()
  } catch {
    // A table that cannot be read falls back key by key to English, as a missing string always has.
  }
}

/*
 * The language last drawn in, kept in this window's own storage: the settings
 * only arrive once the backend answers, and by then a table that is its own
 * chunk should already be in hand. Only a hint - the settings still decide.
 */
const REMEMBERED = "mcode.language"

export function rememberLanguage(id: Language): void {
  try {
    localStorage.setItem(REMEMBERED, id)
  } catch {
    // No storage (a private or broken profile): the table is fetched when asked for instead.
  }
}

export function rememberedLanguage(): Language | undefined {
  try {
    const id = localStorage.getItem(REMEMBERED)
    return LANGUAGES.find((entry) => entry.id === id)?.id
  } catch {
    return undefined
  }
}

export function t(key: string, params?: Record<string, string | number>): string {
  const value = TABLES[language.value]?.[key] ?? en[key] ?? key
  if (!params) return value
  return Object.entries(params).reduce((out, [name, param]) => out.split(`{${name}}`).join(String(param)), value)
}

/*
 * A counted string in the reader's language.
 *
 * `t` has no plural selection, so a counted key is stored once per form -
 * `_one`, `_few`, `_many`, `_other`, the forms MiMo's own tables carry, and
 * `_two`, `_zero` for Arabic's dual and zero (every table carries them; the
 * others repeat their `_other`) - and this picks the one the language's rules
 * ask for.
 */
const KEPT = new Set(["zero", "one", "two", "few", "many"])

export function tn(key: string, count: number): string {
  let form = "other"
  try {
    const picked = new Intl.PluralRules(language.value).select(count)
    if (KEPT.has(picked)) form = picked
  } catch {
    // A language tag the runtime does not know keeps `_other`.
  }
  const said = t(`${key}_${form}`, { count })
  // A table without that form says `_other`, rather than the key itself.
  return said === `${key}_${form}` ? t(`${key}_other`, { count }) : said
}

/**
 * Every key the menu bar asks for, so it can be built in the main process.
 *
 * This has to stay in step with the L() calls in src/main/menu.ts: a key the
 * menu asks for and this list omits is not an error anywhere, it simply falls
 * back to the English default written beside the call.
 */
const MENU_KEYS = [
  "menu.about", "menu.hide", "menu.hideOthers",
  // MiMo's About box, drawn by the main process.
  "menu.aboutVersion", "menu.aboutOk",
  "menu.file", "menu.settings",
  "menu.edit", "menu.undo", "menu.redo",
  "edit.cut", "edit.copy", "edit.paste", "edit.selectAll",
  // The native text menu and the task notifications main builds.
  "edit.copyImage", "edit.copyImageAddress", "notify.done", "notify.confirm", "notify.failed", "notify.chat",
  "menu.view",
  "menu.reload",
  "menu.resetZoom", "menu.zoomIn", "menu.zoomOut",
  "menu.window", "menu.minimize",
  "menu.newTask", "menu.openFolder", "menu.fileClose", "menu.unhide", "menu.quitApp",
  "menu.forceReload", "menu.developerTools", "menu.enterFullscreen", "menu.zoomWindow",
  // The tray's menu is built out here too, and rebuilt when these change.
  "tray.open",
  // The notification main shows before quitting into the installer.
  "update.installingTitle", "update.installingBody",
  // The right-click menu of a page in the browser panel, popped by src/main/browser-page.ts.
  "rp.browser.ctx.openLinkNewTab", "rp.browser.ctx.copyLink", "rp.browser.ctx.copyImage", "rp.browser.ctx.copyImageUrl",
  "rp.browser.ctx.back", "rp.browser.ctx.forward", "rp.browser.ctx.reload",
]

/**
 * Hands the menu bar its labels in the current language.
 *
 * Menus are built by Electron in the main process, which has no table of its
 * own; sending the finished strings keeps the translations in one place.
 */
export function publishMenuLabels(): void {
  const labels: Record<string, string> = {}
  for (const key of MENU_KEYS) labels[key] = t(key)
  window.mcode?.menuLabels(labels)
}

/**
 * What a conversation is called before anything has named it.
 *
 * MiMo turns its engine's placeholder into 未命名对话 - the conversation has no
 * title yet, which is not the same thing as it being new - so this says that
 * rather than 新建会话.
 */
export function sessionTitle(title: string): string {
  return title === "New session" ? t("session.untitled") : title
}

/**
 * Token counts the way a context window is talked about: 39.2K, 1.0M - one
 * decimal with a point and a capital K in every language, as MiMo's composer
 * writes them.
 */
export function compactTokens(count: number): string {
  if (count >= 1_000_000) return `${(count / 1_000_000).toFixed(1)}M`
  if (count >= 1_000) return `${(count / 1_000).toFixed(1)}K`
  return String(count)
}

/*
 * Building an Intl.DateTimeFormat costs far more than using one: a transcript
 * stamps every question and answer, and making a fresh formatter for each was
 * 23ms of a switch to a 160-turn conversation. Kept per language and options.
 */
const formatters = new Map<string, Intl.DateTimeFormat>()

/**
 * Throws the kept formatters away.
 *
 * A formatter resolves its time zone when it is built, so one kept from before
 * the machine moved zone - the traveller who lands and changes the clock, or a
 * check that runs under a zone of its own - would keep writing yesterday's
 * offset until the app restarted. The window calls this when it comes back to
 * the front, which is when a zone change can first be seen.
 */
export function refreshDateFormatters(): void {
  formatters.clear()
}

function formatterFor(tag: string, options?: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${tag}\n${options ? JSON.stringify(options) : ""}`
  let formatter = formatters.get(key)
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(tag, options)
    formatters.set(key, formatter)
  }
  return formatter
}

/**
 * The one date formatter: a moment in the interface language and that
 * language's own default calendar - MiMo's Intl.DateTimeFormat(language) for
 * conversation dates. Every date the interface writes goes through here, so
 * Thai reads the Buddhist year (2569) on every page rather than on some.
 */
export function dateIn(value: number | Date, options?: Intl.DateTimeFormatOptions): string {
  const date = typeof value === "number" ? new Date(value) : value
  try {
    return formatterFor(language.value, options).format(date)
  } catch {
    return date.toLocaleDateString(undefined, options)
  }
}

/** MiMo's unpadded Y/M/D (2026/9/20), its year, month and day counted in that same calendar. */
export function calendarDate(value: number): string {
  try {
    const parts = new Intl.DateTimeFormat(language.value, { year: "numeric", month: "numeric", day: "numeric" }).formatToParts(new Date(value))
    const part = (type: string) => parts.find((entry) => entry.type === type)?.value ?? ""
    const [year, month, day] = [part("year"), part("month"), part("day")]
    if (year && month && day) return `${year}/${month}/${day}`
  } catch {
    // A tag the runtime does not know falls through to the plain calendar.
  }
  const date = new Date(value)
  return `${date.getFullYear()}/${date.getMonth() + 1}/${date.getDate()}`
}

/** A calendar day kept as YYYY-MM-DD, as a short month and day in the interface language: "Sep 20", "9月20日". */
export function dayLabel(key: string): string {
  const [year, month, day] = key.split("-").map(Number)
  if (!year || !month || !day) return key
  return dateIn(new Date(year, month - 1, day), { month: "short", day: "numeric" })
}

/**
 * Relative time, phrased by the active language rather than the OS locale.
 *
 * MiMo's rule, floored: under a minute is 刚刚, then minutes, hours and days,
 * and from 30 days on the date itself in the interface language.
 */
export function ago(value: number): string {
  const seconds = Math.floor((Date.now() - value) / 1000)
  if (seconds < 60) return t("time.justNow")
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return tn("time.minutesAgo", minutes)
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return tn("time.hoursAgo", hours)
  const days = Math.floor(hours / 24)
  if (days < 30) return tn("time.daysAgo", days)
  return dateIn(value)
}
